var HUMAN_STATUSES = [
  "needs_plan_approval",
  "needs_adr_approval",
  "needs_human_decision",
  "needs_triage",
  "blocked"
];
var TerminalAttention = class {
  constructor(options) {
    this.options = options;
    this.now = options.now ?? (() => performance.now());
    const { env } = options;
    this.sequence = options.platform !== "darwin" || !options.interactiveTerminal || !options.output.isTTY || env.BANZAI_ATTENTION === "off" || [env.CI, env.TMUX, env.STY].some((value) => Boolean(value)) || env.TERM === "dumb" ? null : env.TERM_PROGRAM === "Apple_Terminal" ? "\x07" : env.TERM_PROGRAM === "iTerm.app" ? "\x1B]1337;RequestAttention=once\x07" : null;
  }
  sequence;
  now;
  async run(operation) {
    if (this.sequence === null) {
      return await operation();
    }
    const started = this.now();
    const state = await operation();
    if (this.now() - started >= 3e4 && HUMAN_STATUSES.includes(state.status)) {
      this.requestAttention(this.sequence);
    }
    return state;
  }
  requestAttention(sequence) {
    const { output } = this.options;
    if (output.destroyed || !output.writable) {
      return;
    }
    const ignoreError = () => {
    };
    output.once("error", ignoreError);
    try {
      output.write(sequence, (error) => {
        if (!error) {
          output.removeListener("error", ignoreError);
        }
      });
    } catch {
      output.removeListener("error", ignoreError);
    }
  }
};

